<div class="page-heading"><div><span class="section-kicker">ADMINISTRATION</span><h1>System health</h1><p>Read-only operational checks. Manual items are not proof of deployment safety or recoverability.</p></div></div><section class="card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Check</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach($checks as $check): ?><tr><th scope="row"><?= e($check['name']) ?></th><td><span class="badge <?= $check['state']==='pass'?'bg-success':($check['state']==='action'?'bg-danger':'bg-secondary') ?>"><?= e(ucfirst($check['state'])) ?></span></td><td><?= e($check['detail']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><p class="small text-secondary mb-0">Credentials, encryption keys, hashes, raw database errors and private record contents are excluded. Refresh this page after completing a manual configuration change.</p></div></section>
